'use strict';

import { ProtocolReader } from './parseProtocol.js';

/**
 * Determines whether the specified URL is absolute
 *
 * @param {string} url The URL to test
 *
 * @returns {boolean} True if the specified URL is absolute, otherwise false
 */
class AbsoluteURL {
  constructor() {
    this.schemePattern = /^[a-z][a-z\d+\-.]*$/i;
    this.authorityPrefix = '//';
  }

  isAbsolute(candidate) {
    if (candidate.length < this.authorityPrefix.length) {
      return false;
    }

    // A URL is considered absolute if it begins with "<scheme>://" or "//" (protocol-relative URL).
    // RFC 3986 defines scheme name as a sequence of characters beginning with a letter and followed
    // by any combination of letters, digits, plus, period, or hyphen.
    if (candidate.firstChar === this.authorityPrefix.charAt(0) &&
        candidate.secondChar === this.authorityPrefix.charAt(1)) {
      return true;
    }

    if (!candidate.schemeName || !this.schemePattern.test(candidate.schemeName)) {
      return false;
    }

    return candidate.afterScheme.charAt(0) === this.authorityPrefix.charAt(0) &&
      candidate.afterScheme.charAt(1) === this.authorityPrefix.charAt(1);
  }
}

const protocolReader = new ProtocolReader();
const absoluteURL = new AbsoluteURL();

export default function isAbsoluteURL(url) {
  return absoluteURL.isAbsolute(protocolReader.read(url));
}

